# detect outputs relative to rows patterns, maybe 6 and 5 objects represent two overlapping 4x4 shapes; output marks pixels of a third pattern derived from cellwise sum of neighbor (?)
# object as binary matrix. Try identify O = boolean (A transformed) op (B transformed) where rotations/reflections, matching all examples.
examples=[
(['1111','1000','1011','0010'],['1010','1100','0011','0110'],['0000','0011','0100','1001']),
(['0110','0101','0111','1000'],['1110','1001','1111','0101'],['0001','0010','0000','0010']),
(['1110','1000','1000','0111'],['1011','0111','0000','1100'],['0000','0000','0111','0000'])]
def rot(g):return [''.join(g[3-j][i] for j in range(4)) for i in range(4)]
def flip(g):return [r[::-1] for r in g]
for ka in range(4):
 for fa in range(2):
  for kb in range(4):
   for fb in range(2):
    for op in range(5):
     ok=True
     for A,B,O in examples:
      X=A;Y=B
      if fa:X=flip(X)
      for _ in range(ka):X=rot(X)
      if fb:Y=flip(Y)
      for _ in range(kb):Y=rot(Y)
      Z=[]
      for y in range(4):
       s=''
       for x in range(4):
        a=X[y][x]=='1';b=Y[y][x]=='1'
        val=[a and b,a or b,a!=b,a and not b,b and not a][op]
        s+='1' if val else '0'
       Z.append(s)
      if Z!=O:ok=False;break
     if ok:print('all match',ka,fa,kb,fb,op)
